private fun initLivePreview(context: Context, scope: CoroutineScope): LivePreview {
    val livePreview = LivePreview(context)
    var processingTimeMs by mutableLongStateOf(0L)
    var lastProcessingUiUpdateTime by mutableLongStateOf(0L)

    fun assignPriorityAndRegister(tid: Int, onReady: (Int) -> Unit, activeThreads: MutableList<Int>, perfOptimizer: PerformanceOptimizer) {
        synchronized(activeThreads) {
            if (!activeThreads.contains(tid)) {
                android.os.Process.setThreadPriority(tid, android.os.Process.THREAD_PRIORITY_URGENT_DISPLAY)
                activeThreads.add(tid)
                perfOptimizer.updateThreads(activeThreads.toIntArray())
            }
        }
    }

    livePreview.setOnFrameProcessedListener { timeMs ->
        processingTimeMs = timeMs
        perfOptimizer.reportActualWorkDuration(timeMs * 1_000_000L)
        val now = System.currentTimeMillis()
        if (now - lastProcessingUiUpdateTime > 500) {
            processingTimeMs = timeMs
            lastProcessingUiUpdateTime = now
        }
    }

    livePreview.setOnVideoThreadIdAvailableListener { assignPriorityAndRegister(it, {}, mutableListOf(), PerformanceOptimizer(android.content.ContextWrapper(context))) }
    livePreview.setOnGlThreadIdAvailableListener { assignPriorityAndRegister(it, {}, mutableListOf(), PerformanceOptimizer(android.content.ContextWrapper(context))) }
    livePreview.setOnIspThreadIdAvailableListener { assignPriorityAndRegister(it, {}, mutableListOf(), PerformanceOptimizer(android.content.ContextWrapper(context))) }

    return livePreview
}

private fun java.util.concurrent.ExecutorService.registerTids(
    scope: kotlinx.coroutines.CoroutineScope,
    initialThreads: intArrayOf,
    perfOptimizer: PerformanceOptimizer
) {
    val tids = mutableListOf<Int>()
    val count = 2
    val latch = java.util.concurrent.CountDownLatch(count)

    repeat(count) {
        execute {
            val tid = android.os.Process.myTid()
            synchronized(tids) { tids.add(tid) }
            latch.countDown()
        }
    }

    scope.launch(kotlinx.coroutines.Dispatchers.IO) {
        latch.await()
    }

    if (tids.isNotEmpty()) {
        // Threads registered externally
    }
}

private fun checkAllPermissions(context: Context): Boolean {
    return ContextCompat.checkSelfPermission(context, Manifest.permission.CAMERA) == PackageManager.PERMISSION_GRANTED &&
        ContextCompat.checkSelfPermission(context, Manifest.permission.RECORD_AUDIO) == PackageManager.PERMISSION_GRANTED &&
        ContextCompat.checkSelfPermission(context, Manifest.permission.ACCESS_FINE_LOCATION) == PackageManager.PERMISSION_GRANTED
}

private fun Context.unRegisterRecordingReceiver() {
    (this.findActivity() as? MainActivity)?.let { activity ->
        try {
            this.unregisterReceiver(activity.getRecordingReceiver())
        } catch (_: Exception) { }
    }
}

private fun stopRecording(
    context: Context, livePreview: LivePreview, sensorCapture: SensorCapture,
    captureVideo: CaptureVideo, currentVideoFile: File?, locationTracker: LocationTracker,
    executor: java.util.concurrent.ExecutorService, onFileCleared: () -> Unit
) {
    captureVideo.stopRecording()
    livePreview.stopVideoRecording()
    sensorCapture.setAwbLock(false)

    currentVideoFile?.let { file ->
        val loc = locationTracker.getLastLocation()
        executor.execute { saveVideoToGallery(context, file, loc) }
    }
    onFileCleared()
}

private fun configureCameraListeners(sensorCapture: SensorCapture, livePreview: LivePreview) {
    sensorCapture.setOnSensorImageAvailableListener(object : SensorCapture.OnSensorImageAvailableListener {
        override fun onSensorImageAvailable(reader: ImageReader) {
            try {
                val image = reader.acquireNextImage()
                image?.let { livePreview.updateSensorImage(it) }
            } catch (e: Exception) {
                Log.e("MainActivity", "Error acquiring image", e)
            }
        }
    })

    var currentFlickerHz by mutableIntStateOf(0)
    var manualExposureTimeNs by mutableLongStateOf(0L)
    var currentIso by mutableIntStateOf(0)
    var currentExposureTimeNs by mutableLongStateOf(0L)
    var lastMetadataUiUpdateTime by mutableLongStateOf(0L)

    sensorCapture.setOnMetadataAvailableListener { iso, exposureTimeNs, dynamicBlackLevel, awbGains, colorMatrix, intrinsics, flickerHz ->
        livePreview.setIso(iso)
        livePreview.setExposureTime(exposureTimeNs)

        if (flickerHz != currentFlickerHz) {
            currentFlickerHz = flickerHz
            if (flickerHz > 0 && manualExposureTimeNs > 0) {
                val period = if (flickerHz == 50) 10_000_000L else 8_333_333L
                val snapped = Math.max(1L, Math.round(manualExposureTimeNs.toDouble() / period) * period)
                if (snapped != manualExposureTimeNs) {
                    manualExposureTimeNs = snapped
                    sensorCapture.setManualExposureTime(snapped)
                }
            }
        }

        val now = System.currentTimeMillis()
        if (now - lastMetadataUiUpdateTime > 500) {
            currentIso = iso
            currentExposureTimeNs = exposureTimeNs
            lastMetadataUiUpdateTime = now
        }

        livePreview.setBlackLevelPattern(dynamicBlackLevel ?: floatArrayOf(64f, 64f, 64f, 64f))
        if (awbGains != null && false) {
            livePreview.setWbGains(
                maxOf(0.1f, awbGains[0]),
                maxOf(0.1f, awbGains[1]),
                maxOf(0.1f, awbGains[2])
            )
        }

        if (colorMatrix != null) {
            livePreview.setColorMatrix(colorMatrix)
        }
    }
}

private fun openCameraAndSetParameters(
    sensorCapture: SensorCapture, selectedCameraId: String, selectedPhysicalId: String?,
    rawPreviewSurface: Surface?, livePreview: LivePreview, autoLevelsMode: Int,
    showHistogram: Boolean, logRange: Float, useSpatialDenoise: Int, useFalseColor: Int,
    highlightRecoveryEnabled: Boolean, isComparisonEnabled: Boolean,
    cameras: List<CameraInfo>, context: Context, perfOptimizer: PerformanceOptimizer
): CameraInfo? {
    val effectiveId = selectedPhysicalId ?: selectedCameraId
    val cameraInfo = cameras.find { it.id == selectedCameraId && (it.physicalId == selectedPhysicalId || (it.physicalId == null && selectedPhysicalId == null)) }

    val isFront = cameraInfo?.facing == CameraCharacteristics.LENS_FACING_FRONT
    val sensorOrientation = sensorCapture.getSensorOrientation(effectiveId)
    val cfaPattern = sensorCapture.getCfaPattern(effectiveId)
    val blackLevel = sensorCapture.getBlackLevelPattern(effectiveId)
    val whiteLevel = sensorCapture.getWhiteLevel(effectiveId, selectedCameraId)
    val distortion = sensorCapture.getLensDistortion(effectiveId)

    with(livePreview) {
        setIsMirrored(isFront)
        setSensorOrientation(sensorOrientation)
        setCfaPattern(cfaPattern)
        setBlackLevelPattern(blackLevel)
        setWhiteLevel(whiteLevel.toFloat())
        setDistortion(distortion)
        setBlackLevelOffset(0.0f)
        setAutoLevelsMode(autoLevelsMode)
        setShowHistogram(showHistogram)
        setLogRange(logRange)
        setPipelineSettings(useSpatialDenoise, useFalseColor, highlightRecoveryEnabled)
    }

    cameraInfo?.maxPreviewResolution?.let { size ->
        livePreview.setRawPreviewResolution(size.width, size.height)
    }

    sensorCapture.openCamera(selectedCameraId, selectedPhysicalId, rawPreviewSurface)
    perfOptimizer.enableSustainedPerformanceMode(context.findActivity()?.window ?: return cameraInfo)
    perfOptimizer.startPerformanceSession(intArrayOf(android.os.Process.myTid()))

    return cameraInfo
}

private fun configureCameraControls(
    sensorCapture: SensorCapture, livePreview: LivePreview,
    aeCompensation: Int, manualIso: Int, manualExposureTimeNs: Long,
    lockExposure: Boolean, useOis: Boolean, cameraInfo: CameraInfo?
) {
    currentIsoRange = sensorCapture.getIsoRange()
    val rawShutterRange = sensorCapture.getShutterRange()
    val maxShutterNs = 1_000_000_000L / 30
    currentShutterRange = android.util.Range(rawShutterRange.lower, minOf(rawShutterRange.upper, maxShutterNs))
    aeCompensationRange = sensorCapture.getExposureCompensationRange()
    aeCompensationStep = sensorCapture.getExposureCompensationStep()

    with(sensorCapture) {
        setManualIso(manualIso)
        setManualExposureTime(manualExposureTimeNs)
        setExposureCompensation(aeCompensation)
        setAeLock(lockExposure)
        setUseOis(useOis)
    }
}

