private fun CameraPreviewContent(
    context: Context, livePreview: LivePreview, glSurfaceView: GLSurfaceView,
    isShowingRawPreview: Boolean, showDebugData: Boolean, processingTimeMs: Long,
    currentIso: Int, currentExposureTimeNs: Long, isRecording: Boolean, recordingDuration: Int,
    zoomValue: Float, zoomRange: ClosedFloatingPointRange<Float>,
    isRecordingLocked: Boolean, lockDragOffset: Float, lockThreshold: android.util.SizeF,
