            text = buildTimeText,
            modifier = Modifier.padding(horizontal = 12.dp, vertical = 4.dp),
            color = Color.White,
            style = MaterialTheme.typography.labelMedium
        )
    }
}

fun formatShutterSpeed(exposureTimeNs: Long): String {
    if (exposureTimeNs <= 0) return "0s"

    val seconds = exposureTimeNs.toDouble() / 1_000_000_000.0

    val standardDenominators = floatArrayOf(
        1f, 1.3f, 1.5f, 2f, 2.5f, 3f, 4f, 5f, 6f, 8f, 10f, 15f, 20f, 25f, 30f,
        40f, 50f, 60f, 80f, 100f, 125f, 150f, 200f, 250f, 320f, 400f, 500f, 640f,
        800f, 1000f, 1250f, 1600f, 2000f, 2500f, 3200f, 4000f, 5000f, 6400f, 8000f
    )

    if (seconds < 1.0) {
        val denominator = 1f / seconds.toFloat()
        var closest = standardDenominators[0]
        var minDiff = Float.MAX_VALUE
        for (d in standardDenominators) {
            val diff = kotlin.math.abs(d - denominator)
            if (diff < minDiff) {
                minDiff = diff
                closest = d
            }
        }
        val rounded = kotlin.math.round(closest).toLong()
        return if (rounded > 1) "1/$rounded" + "s" else "$rounded" + "s"
    } else {
        return if (seconds == seconds.toInt().toDouble()) {
            "${seconds.toInt()}s"
        } else {
            String.format("%.1f", seconds) + "s"
        }
    }
}

fun Context.findActivity(): androidx.activity.ComponentActivity? = when (this) {
    is androidx.activity.ComponentActivity -> this
    is android.content.ContextWrapper -> baseContext.findActivity()
    else -> null
}

